public class OrderCdcConsumer {

    private final ElasticsearchClient es;

    @KafkaListener(topics = "pg.public.orders", groupId = "orders-es-sync")
    public void onChange(ConsumerRecord<String, JsonNode> rec) throws IOException {
        JsonNode payload = rec.value().get("payload");
        String op = payload.get("op").asText();         // c=create, u=update, d=delete, r=snapshot
        JsonNode after = payload.get("after");

        if ("d".equals(op) || after == null || after.isNull()) {
            es.delete(d -> d.index("orders").id(rec.key()));
            return;
        }

        OrderDoc doc = mapper.treeToValue(after, OrderDoc.class);
        es.index(i -> i.index("orders").id(doc.getId().toString()).document(doc));
    }
}
