}

// 2) Query: $search runs inside the same aggregation pipeline
db.products.aggregate([
  { $search: {
      index: "products_search",
      compound: {
        must:   [{ text: { query: "noise cancelling headphones", path: ["name", "description"] } }],
        filter: [{ range: { path: "price", lte: 300 } },
                 { equals: { path: "category", value: "audio" } }]
      },
      highlight: { path: ["name", "description"] }
  }},
  { $limit: 20 }
]);
